// Presence diff sketch
function diffPresence(prev, next) {
  const toAdd = [];
  const toRemove = [];
  const nextSet = new Set(next.map(n => n.userId));
  for (const u of prev) if (!nextSet.has(u.userId)) toRemove.push(u);
  for (const n of next) if (!prev.find(p => p.userId === n.userId)) toAdd.push(n);
  return { toAdd, toRemove };
}

